{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Our main living systematic review of interventions is collecting results from randomised or non-randomised trials of mental health interventions conducted in any population during COVID-19. For trials to be included among those with results posted online in the main review, all participants had to be enrolled after December 31, 2019, when China first reported on COVID-19 to the World Health Organization. Eligible interventions included any intervention described as designed to address COVID-19 mental health challenges or primarily addressing mental health symptoms from COVID-19. Trials that were not mental health interventions and primarily targeted non-mental health outcomes (e.g., exercise with primary outcome physical activity) were excluded, even if mental health outcomes were reported. Eligible comparators included: (1) inactive control conditions (e.g., no treatment, waitlist) and (2) other eligible interventions. Eligible outcomes were defined broadly and included general mental health, mental health quality of life, anxiety symptoms, depression symptoms, stress, loneliness, anger, grief, burnout, and other emotional states. To be eligible, trials had to report outcomes collected at least 1 week after intervention initiation and include at least 10 total participants.",
      "reason": "Specifies study characteristics including eligible study designs (randomised or non-randomised trials), settings (any population during COVID-19), interventions, comparators, outcomes, follow-up requirements (outcomes at least 1 week after initiation), and participant enrollment criteria."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "There were no restrictions on language or publication format.",
      "reason": "Language and publication status are specified as having no restrictions, but dissemination year is not explicitly mentioned as an eligibility criterion for reports."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not distinguish between exclusion due to outcomes not measured versus not reported; eligibility criteria focus on other aspects such as intervention type and study design, and this distinction is not addressed in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "We did not pool results across trials because of substantial heterogeneity of populations, interventions, and outcomes and concerns about the risk of bias. Instead, we reported results descriptively.",
      "reason": "No synthesis was performed, so groups for synthesis are not specified; however, the decision to report results descriptively is mentioned, but groups used in descriptive reporting are not explicitly linked to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We did not include nonrandomised studies because such studies are highly prone to bias when intervention and control groups are self-selected or there is no control group. Additionally, to include only trials likely to provide evidence useful for policy and practice decisions, we excluded trials of brief single-session interventions (e.g., 30 min) with no subsequent follow-up, and we excluded non-randomised studies.",
      "reason": "Rationales are provided for notable restrictions on study eligibility, such as excluding non-randomised studies due to bias and brief interventions due to policy and practice relevance."
    }
  ],
  "confidence": 80
}

